import { dispatchUpsellAccepted } from '../events';
import { state } from '../store';
import { Checkout, LineItem, Product, Upsell } from '../../../types';

describe('upsell store', () => {
  beforeEach(() => {
    localStorage.clear(); // reset the once-per-line-item accepted guard.
    state.upsell = { id: 'upsell-1' } as Upsell;
    state.product = { id: 'product-1', name: 'LED Lantern' } as Product;
  });

  describe('events', () => {
    it('emits scUpsellAccepted with checkout, line item, upsell and product detail', () => {
      const listener = jest.fn();
      window.addEventListener('scUpsellAccepted', listener);

      dispatchUpsellAccepted({ id: 'checkout-1', currency: 'usd' } as Checkout, { id: 'line-item-1', total_amount: 16800, quantity: 1 } as LineItem);

      expect(listener).toBeCalledTimes(1);
      expect(listener.mock.calls[0][0].detail).toEqual({
        checkout: expect.objectContaining({ id: 'checkout-1' }),
        line_item: expect.objectContaining({ id: 'line-item-1', total_amount: 16800 }),
        upsell: expect.objectContaining({ id: 'upsell-1' }),
        product: expect.objectContaining({ id: 'product-1' }),
      });

      window.removeEventListener('scUpsellAccepted', listener);
    });

    it('emits only once per upsell line item', () => {
      const listener = jest.fn();
      window.addEventListener('scUpsellAccepted', listener);

      dispatchUpsellAccepted({ id: 'checkout-1' } as Checkout, { id: 'line-item-1' } as LineItem);
      dispatchUpsellAccepted({ id: 'checkout-1' } as Checkout, { id: 'line-item-1' } as LineItem);

      expect(listener).toBeCalledTimes(1);

      // a different line item (e.g. a genuine re-purchase) fires its own event.
      dispatchUpsellAccepted({ id: 'checkout-1' } as Checkout, { id: 'line-item-2' } as LineItem);

      expect(listener).toBeCalledTimes(2);

      window.removeEventListener('scUpsellAccepted', listener);
    });

    it('does not emit without a line item id', () => {
      const listener = jest.fn();
      window.addEventListener('scUpsellAccepted', listener);

      dispatchUpsellAccepted({ id: 'checkout-1' } as Checkout, {} as LineItem);
      dispatchUpsellAccepted({ id: 'checkout-1' } as Checkout, undefined);

      expect(listener).toBeCalledTimes(0);

      window.removeEventListener('scUpsellAccepted', listener);
    });
  });
});
